export type RoomId = "dining" | "kitchen" | "freezer";

export type RoomRect = {
  id: RoomId;
  label: string;
  x: number;
  z: number;
  w: number;
  d: number;
};

export type FloorLayout = {
  width: number;
  depth: number;
  height: number;
  thickness: number;
  rooms: RoomRect[];
  freezerRemoved: boolean;
};

export type WallRole = "shell" | "divider" | "freezer";

export type WallRect = {
  x: number;
  z: number;
  w: number;
  d: number;
  role: WallRole;
};

export type StructureEdit =
  | { kind: "remove-freezer" }
  | { kind: "restore-freezer" }
  | { kind: "shift-wall"; meters: number };

const MIN_ROOM = 2.4;

export function buildLayout(squareFeet: number): FloorLayout {
  const area = Math.max(squareFeet, 800) * 0.092903;
  let depth = Math.sqrt(area / 1.55);
  let width = depth * 1.55;
  const cap = 20;
  if (width > cap) {
    const scale = cap / width;
    width *= scale;
    depth *= scale;
  }
  const diningW = width * 0.58;
  const right = width - diningW;
  const kitchenD = depth * 0.62;
  return {
    width,
    depth,
    height: 3.05,
    thickness: 0.16,
    freezerRemoved: false,
    rooms: [
      { id: "dining", label: "Dining", x: 0, z: 0, w: diningW, d: depth },
      { id: "kitchen", label: "Kitchen", x: diningW, z: 0, w: right, d: kitchenD },
      { id: "freezer", label: "Freezer", x: diningW, z: kitchenD, w: right, d: depth - kitchenD },
    ],
  };
}

export function room(layout: FloorLayout, id: RoomId): RoomRect {
  const found = layout.rooms.find((entry) => entry.id === id);
  if (!found) throw new Error(`Missing room ${id}`);
  return found;
}

export function removeFreezer(layout: FloorLayout): FloorLayout {
  if (layout.freezerRemoved) return layout;
  const freezer = room(layout, "freezer");
  const kitchen = room(layout, "kitchen");
  return {
    ...layout,
    freezerRemoved: true,
    rooms: layout.rooms.map((entry) => {
      if (entry.id === "kitchen") return { ...entry, d: kitchen.d + freezer.d };
      if (entry.id === "freezer") return { ...entry, d: 0 };
      return entry;
    }),
  };
}

export function restoreFreezer(layout: FloorLayout): FloorLayout {
  if (!layout.freezerRemoved) return layout;
  const kitchen = room(layout, "kitchen");
  const freezerD = Math.max(2, kitchen.d * 0.38);
  const kitchenD = Math.max(MIN_ROOM, kitchen.d - freezerD);
  return {
    ...layout,
    freezerRemoved: false,
    rooms: layout.rooms.map((entry) => {
      if (entry.id === "kitchen") return { ...entry, d: kitchenD };
      if (entry.id === "freezer") {
        return { ...entry, x: kitchen.x, z: kitchen.z + kitchenD, w: kitchen.w, d: kitchen.d - kitchenD };
      }
      return entry;
    }),
  };
}

/** Positive meters give that width to the dining room and take it from the kitchen. */
export function shiftServiceWall(layout: FloorLayout, meters: number): FloorLayout {
  const dining = room(layout, "dining");
  const next = Math.min(layout.width - MIN_ROOM, Math.max(MIN_ROOM, dining.w + meters));
  const right = layout.width - next;
  return {
    ...layout,
    rooms: layout.rooms.map((entry) => {
      if (entry.id === "dining") return { ...entry, w: next };
      return { ...entry, x: next, w: right };
    }),
  };
}

export function applyStructure(layout: FloorLayout, edit: StructureEdit): FloorLayout {
  if (edit.kind === "remove-freezer") return removeFreezer(layout);
  if (edit.kind === "restore-freezer") return restoreFreezer(layout);
  return shiftServiceWall(layout, edit.meters);
}

export function layoutWalls(layout: FloorLayout): WallRect[] {
  const t = layout.thickness;
  const { width: W, depth: D } = layout;
  const dining = room(layout, "dining");
  const kitchen = room(layout, "kitchen");
  const freezer = room(layout, "freezer");
  const walls: WallRect[] = [];
  const push = (rect: Omit<WallRect, "role">, role: WallRole) => {
    if (rect.w > 0.05 && rect.d > 0.05) walls.push({ ...rect, role });
  };

  push({ x: 0, z: 0, w: W, d: t }, "shell");
  push({ x: 0, z: 0, w: t, d: D }, "shell");
  push({ x: W - t, z: 0, w: t, d: D }, "shell");

  const doorW = 1.4;
  const doorX = Math.min(Math.max(1.05, dining.w * 0.36), Math.max(1.05, dining.w - doorW - 0.5));
  if (dining.w > doorW + 1.4) {
    push({ x: 0, z: D - t, w: doorX, d: t }, "shell");
    push({ x: doorX + doorW, z: D - t, w: Math.max(0, W - doorX - doorW), d: t }, "shell");
  } else {
    push({ x: 0, z: D - t, w: W, d: t }, "shell");
  }

  const splitX = dining.w - t / 2;
  const gap = 1.25;
  const gapZ = kitchen.z + Math.min(Math.max(kitchen.d * 0.28, 0.45), Math.max(kitchen.d - gap - 0.3, 0.3));
  const gapEnd = gapZ + gap;
  if (kitchen.d > gap + 1) {
    push({ x: splitX, z: 0, w: t, d: gapZ }, "divider");
    push({ x: splitX, z: gapEnd, w: t, d: Math.max(0, D - gapEnd) }, "divider");
  } else {
    push({ x: splitX, z: 0, w: t, d: D }, "divider");
  }

  if (freezer.d > 0.2) {
    push({ x: kitchen.x, z: kitchen.z + kitchen.d - t / 2, w: kitchen.w, d: t }, "freezer");
  }

  return walls;
}

export function hitsWall(layout: FloorLayout, x: number, z: number, radius: number): boolean {
  if (x < radius || z < radius || x > layout.width - radius || z > layout.depth - radius) return true;
  for (const wall of layoutWalls(layout)) {
    const nearestX = Math.max(wall.x, Math.min(x, wall.x + wall.w));
    const nearestZ = Math.max(wall.z, Math.min(z, wall.z + wall.d));
    const dx = x - nearestX;
    const dz = z - nearestZ;
    if (dx * dx + dz * dz < radius * radius) return true;
  }
  return false;
}

export function diningCenter(layout: FloorLayout): { x: number; z: number } {
  const dining = room(layout, "dining");
  return { x: dining.x + dining.w / 2, z: dining.z + dining.d / 2 };
}
